head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil18000";
scwin.form = null;
scwin.maxLenCheckVars = undefined;
scwin.maxLenCheckNames = undefined;
scwin.maxLenCheckMax = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.onload();
        try {
            if ($c.util.getComponent("dma_RegisterReq").get("cmstkShrs2") === null) {
                for (let i = 0; i < scwin.form.cmstkShrs2.length; i++) {

                }
            } else {

            }
            if ($c.util.getComponent("dma_RegisterReq").get("prefstkShrs2") === null) {
                for (let i = 0; i < scwin.form.prefstkShrs2.length; i++) {

                }
            } else {

            }
        } catch (err2) { $c.exception.handleError(err2, { notify: 'none', context: 'jldfil18000' }); }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil18000.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil18000' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: entry_edge). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

try { scwin.maxLenCheckVars =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil18000' }); }

try { scwin.maxLenCheckNames =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil18000' }); }

try { scwin.maxLenCheckMax =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil18000' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_sessionFill();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil18000.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_cmstkShrs_onkeyup
 * @description ipt_cmstkShrs 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_cmstkShrs_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        (selfVar.value = $c.num.formatNumber(selfVar.value));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil18000.ipt_cmstkShrs_onkeyup' }); }
};

/**
 * @method
 * @name ipt_prefstkShrs_onkeyup
 * @description ipt_prefstkShrs 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_prefstkShrs_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        (selfVar.value = $c.num.formatNumber(selfVar.value));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil18000.ipt_prefstkShrs_onkeyup' }); }
};

/**
 * @method
 * @name btn_Register_onclick
 * @description btn_Register 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Register_onclick = async function(e){
    try {
        await scwin.register()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil18000.btn_Register_onclick' }); }
};

/**
 * @method
 * @name btn_Update_onclick
 * @description btn_Update 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Update_onclick = async function(e){
    try {
        await scwin.update()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil18000.btn_Update_onclick' }); }
};

/**
 * @method
 * @name btn_Delete_onclick
 * @description btn_Delete 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Delete_onclick = async function(e){
    try {
        await scwin.deleteRegisterReq()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil18000.btn_Delete_onclick' }); }
};

/**
 * @method
 * @name grd_resultList_oncellclick
 * @description grd_resultList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.loadForm(r["outDirName"], r["birthDd"], r["lastEdu"], r["major"], r["career"], r["jobTitle"], r["occupation"], r["starDd"], r["endDd"], r["elctYn"], r["cmstkShrs"], r["prefstkShrs"], r["remk"], r["isurCd"], r["seq"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};

/**
 * @method
 * @name onload
 * @description onload 처리
 * @returns {void}
 * @hidden N
 */
scwin.onload = function () {
    try {
        scwin.form = (document.outDirForm || { elements: [] });
        scwin.onloadDataSet();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil18000.onload" });
    }
};

/**
 * @method
 * @name onloadDataSet
 * @description onload Data Set 처리
 * @returns {void}
 * @hidden N
 */
scwin.onloadDataSet = function () {
    /* empty */
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Register
 * @description Register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Register = async function () {
    const sbmOptions = {
        id: "tx_fn_Register",
        method: "post",
        action: "/support/outDir.do",
        ref: "dma_RegisterReq",
        target: "dlt_resultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Update
 * @description Update 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Update = async function () {
    const sbmOptions = {
        id: "tx_fn_Update",
        method: "post",
        action: "/support/outDir.do",
        ref: "dma_UpdateReq",
        target: "dlt_resultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Delete
 * @description Delete 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Delete = async function () {
    const sbmOptions = {
        id: "tx_fn_Delete",
        method: "post",
        action: "/support/outDir.do",
        ref: "dma_DeleteReq",
        target: "dlt_resultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/support/outDir.do?method=searchOutDir",
        ref: "dma_loadListReq",
        target: "dlt_resultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name loadForm
 * @description load Form 처리
 * @param {*} outDirName outDirName
 * @param {String} birthDd birthDd
 * @param {*} lastEdu lastEdu
 * @param {*} major major
 * @param {*} career career
 * @param {*} jobTitle jobTitle
 * @param {*} occupation occupation
 * @param {String} starDd starDd
 * @param {String} endDd endDd
 * @param {String} elctYn elctYn
 * @param {*} cmstkShrs cmstkShrs
 * @param {*} prefstkShrs prefstkShrs
 * @param {*} remk remk
 * @param {String} isurCd isurCd
 * @param {*} seq seq
 * @returns {void}
 * @hidden N
 */
scwin.loadForm = function (outDirName, birthDd, lastEdu, major, career, jobTitle, occupation, starDd, endDd, elctYn, cmstkShrs, prefstkShrs, remk, isurCd, seq) {
    $c.util.getComponent('ipt_outDirName').setValue(outDirName);
    $c.util.getComponent('cal_birthDd').setValue(scwin.replaceDsp(birthDd));
    $c.util.getComponent('ipt_lastEdu').setValue(lastEdu);
    (($c.util.getComponent('slc_major'))?.setValue?.(major));
    $c.util.getComponent('ipt_career').setValue(career);
    $c.util.getComponent('ipt_jobTitle').setValue(jobTitle);
    (($c.util.getComponent('slc_occupation'))?.setValue?.(occupation));
    $c.util.getComponent('cal_starDd').setValue(scwin.replaceDsp(starDd));
    $c.util.getComponent('cal_endDd').setValue(scwin.replaceDsp(endDd));
    (($c.util.getComponent('slc_elctYn'))?.setValue?.(elctYn));
    $c.util.getComponent('ipt_cmstkShrs').setValue($c.num.formatNumber(cmstkShrs));
    $c.util.getComponent('ipt_prefstkShrs').setValue($c.num.formatNumber(prefstkShrs));
    $c.util.getComponent('ipt_remk').setValue(remk);
    $c.util.getComponent("dma_RegisterReq").set("isurCd", isurCd);
    $c.util.getComponent("dma_RegisterReq").set("seq", seq);
    scwin.onloadDataSet();
};

/**
 * @method
 * @name replaceDsp
 * @description replace Dsp 처리
 * @param {*} dateDsp dateDsp
 * @returns {void}
 * @hidden N
 */
scwin.replaceDsp = function (dateDsp) {
    return dateDsp.replace(/[/,-]/g, '');
};

/**
 * @method
 * @name setSelect
 * @description set Select 처리
 * @param {Object} obj 컴포넌트
 * @param {*} p_value p_value
 * @returns {void}
 * @hidden N
 */
scwin.setSelect = function (obj, p_value) {
    for (let i = 0; i < obj.getItemCount(); i++) {
        if (obj[i].value === p_value) {
            obj[i].selected = true;
        }
    }
};

/**
 * @method
 * @name vailidationLn
 * @description vailidation Ln 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.vailidationLn = async function () {
    if ($c.util.getComponent('ipt_outDirName').getValue()=== null || ($c.util.getComponent('ipt_outDirName').getValue() === null ? '' : String($c.util.getComponent('ipt_outDirName').getValue())) === '') {
        await $c.win.alert("사외이사명을 입력하세요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return false;
    }
    if ($c.util.getComponent('cal_birthDd').getValue().length !== 8) {
        await $c.win.alert("생년월일을 정확히 입력해주십시요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return false;
    }
    if (!await (async () => { const vars = scwin.maxLenCheckVars || []; const names =  scwin.maxLenCheckNames || []; const maxes =  scwin.maxLenCheckMax || []; for (let i = 0; i < vars.length; i++) { const c = $c.util.getComponent(vars[i]); if (!c || !c.getValue) { continue; } const len = $c.str.getByteLength(String(c.getValue() ?? "")); const max = Number(maxes[i]) || 0; if (max && len > max) { await $c.win.alert(String(names[i]) + "의 최대길이(" + max + ")를 \n" + (len - max) + " Byte 만큼 초과하였습니다.\n수정후 저장하세요"); if (c.setFocus) { c.setFocus(); } return false; } } return true; })()) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    if (await scwin.vailidationLn() === false) {
        return;
    }
    scwin.form.action = '/support/outDir.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'insertOutDir');
    await scwin.tx_fn_Register();
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function () {
    if ($c.util.getComponent("dma_RegisterReq").get("isurCd") === null || $c.util.getComponent("dma_RegisterReq").get("isurCd") === "" || $c.util.getComponent("dma_RegisterReq").get("seq") === null || $c.util.getComponent("dma_RegisterReq").get("seq") === "") {
        await $c.win.alert("수정하시려면, 리스트에서 선택후 수정하세요.");
        return;
    }
    if (await scwin.vailidationLn() === false) {
        return;
    }
    scwin.form.action = '/support/outDir.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'updateOutDir');
    await scwin.tx_fn_Update();
};

/**
 * @method
 * @name deleteRegisterReq
 * @description delete Register Req 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteRegisterReq = async function () {
    if ($c.util.getComponent("dma_RegisterReq").get("isurCd") === null || $c.util.getComponent("dma_RegisterReq").get("isurCd") === "" || $c.util.getComponent("dma_RegisterReq").get("seq") === null || $c.util.getComponent("dma_RegisterReq").get("seq") === "") {
        await $c.win.alert("삭제하시려면, 먼저 리스트에서 삭제대상을 선택하세요.");
        return;
    }
    scwin.form.action = '/support/outDir.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'deleteOutDir');
    await scwin.tx_fn_Delete();
};

/**
 * @method
 * @name objValueResetRmComma
 * @description obj Value Reset Rm Comma 처리
 * @param {*} numObj numObj
 * @returns {void}
 * @hidden N
 */
scwin.objValueResetRmComma = function (numObj) {
    if (numObj !== null && numObj !== '') {
        numObj.setValue(scwin.rmComma(numObj.getValue()));
    }
};

/**
 * @method
 * @name rmComma
 * @description rm Comma 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.rmComma = function (str) {
    if (str === null || str === "") {
        return Number(str);
    }
    reg = new RegExp(",", "g");
    return Number(str.replace(reg, ''));
};
